#import <AppKit/AppKit.h>
#import <CoreText/CoreText.h>
static CGContextRef ctx; static CGFloat W=595,H=842,y; static NSString *eventName,*reportTitle; static int page;
static NSString *reportFontName;
static NSFont *font(CGFloat size,BOOL bold){NSFont *base=[NSFont fontWithName:reportFontName?:@"Readex Pro" size:size]?:[NSFont systemFontOfSize:size];return bold?[[NSFontManager sharedFontManager] convertFont:base toHaveTrait:NSBoldFontMask]:base;}
static NSDictionary *attrs(CGFloat size,BOOL bold,NSColor *color){NSMutableParagraphStyle *p=[NSMutableParagraphStyle new];p.lineBreakMode=NSLineBreakByWordWrapping;return @{NSFontAttributeName:font(size,bold),NSForegroundColorAttributeName:color,NSParagraphStyleAttributeName:p};}
static CGFloat textHeight(NSString *s,CGFloat w,CGFloat size){return ceil([s boundingRectWithSize:NSMakeSize(w,10000) options:NSStringDrawingUsesLineFragmentOrigin|NSStringDrawingUsesFontLeading attributes:attrs(size,NO,NSColor.blackColor)].size.height);}
static void text(NSString *s,CGFloat x,CGFloat top,CGFloat w,CGFloat height,CGFloat size,BOOL bold,NSColor *color){[s drawWithRect:NSMakeRect(x,top,w,height) options:NSStringDrawingUsesLineFragmentOrigin|NSStringDrawingUsesFontLeading attributes:attrs(size,bold,color) context:nil];}
static void rect(CGFloat x,CGFloat top,CGFloat w,CGFloat h,NSColor *color){CGContextSetFillColorWithColor(ctx,color.CGColor);CGContextFillRect(ctx,CGRectMake(x,top,w,h));}
static void endPage(void){if(page){text([NSString stringWithFormat:@"%d",page],36,H-28,W-72,18,9,NO,NSColor.grayColor);CGContextRestoreGState(ctx);CGPDFContextEndPage(ctx);}}
static void beginPage(void){endPage();CGPDFContextBeginPage(ctx,NULL);CGContextSaveGState(ctx);CGContextTranslateCTM(ctx,0,H);CGContextScaleCTM(ctx,1,-1);[NSGraphicsContext setCurrentContext:[NSGraphicsContext graphicsContextWithCGContext:ctx flipped:YES]];page++;text(eventName,36,28,W-72,30,18,YES,NSColor.blackColor);text(reportTitle,36,60,W-72,26,13,YES,[NSColor colorWithSRGBRed:.45 green:.16 blue:.65 alpha:1]);y=99;}
static void drawOutline(CGFloat x,CGFloat top,CGFloat w,CGFloat height){CGContextSetStrokeColorWithColor(ctx,[NSColor colorWithSRGBRed:.65 green:.58 blue:.72 alpha:1].CGColor);CGContextSetLineWidth(ctx,.9);CGContextStrokeRect(ctx,CGRectMake(x,top,w,height));}
static void header(NSArray *columns,NSArray *widths){CGFloat x=36;rect(x,y,W-72,25,[NSColor colorWithSRGBRed:.45 green:.16 blue:.65 alpha:1]);for(NSUInteger i=0;i<columns.count;i++){CGFloat w=[widths[i] doubleValue]*(W-72);text(columns[i],x+5,y+5,w-10,20,10,YES,NSColor.whiteColor);drawOutline(x,y,w,25);x+=w;}y+=25;}
static NSColor *orgColor(id rgb){if(![rgb isKindOfClass:NSArray.class]||[rgb count]!=3)return nil;return [NSColor colorWithSRGBRed:[rgb[0] doubleValue] green:[rgb[1] doubleValue] blue:[rgb[2] doubleValue] alpha:1];}
static NSString *cellText(id cell){return [cell isKindOfClass:NSDictionary.class]?cell[@"text"]:[cell description];}
static void drawCell(id cell,CGFloat x,CGFloat top,CGFloat w,CGFloat h){
 if(![cell isKindOfClass:NSDictionary.class]){text(cellText(cell),x,top,w,h,10,NO,NSColor.blackColor);return;}
 NSMutableAttributedString *content=[[NSMutableAttributedString alloc]initWithString:@""];
 for(NSDictionary *run in cell[@"runs"]){NSMutableDictionary *a=[attrs(10,NO,NSColor.blackColor) mutableCopy];NSColor *color=orgColor(run[@"background"]);if(color)a[NSBackgroundColorAttributeName]=color;[content appendAttributedString:[[NSAttributedString alloc]initWithString:run[@"text"]?:@"" attributes:a]];}
 [content drawWithRect:NSMakeRect(x,top,w,h) options:NSStringDrawingUsesLineFragmentOrigin|NSStringDrawingUsesFontLeading context:nil];
}
static void table(NSArray *columns,NSArray *widths,NSArray *rows,NSArray *rowColors){header(columns,widths);NSUInteger rowIndex=0;for(NSArray *row in rows){CGFloat height=27;for(NSUInteger i=0;i<row.count;i++)height=MAX(height,textHeight(cellText(row[i]),[widths[i] doubleValue]*(W-72)-10,10)+12);if(height>H-150)height=H-150;if(y+height>H-42){beginPage();header(columns,widths);}NSColor *highlight=rowIndex<rowColors.count?orgColor(rowColors[rowIndex]):nil;if(highlight)rect(36,y,W-72,height,highlight);else if(rowIndex%2)rect(36,y,W-72,height,[NSColor colorWithSRGBRed:.97 green:.95 blue:.99 alpha:1]);rowIndex++;CGFloat x=36;for(NSUInteger i=0;i<row.count;i++){CGFloat w=[widths[i] doubleValue]*(W-72);drawCell(row[i],x+5,y+6,w-10,height-8);drawOutline(x,y,w,height);x+=w;}y+=height;}}
int main(int argc,const char **argv){@autoreleasepool{if(argc<3)return 2;NSError *error=nil;NSData *input=[[NSFileHandle fileHandleWithStandardInput] readDataToEndOfFile];NSDictionary *data=[NSJSONSerialization JSONObjectWithData:input options:0 error:&error];if(!data){fprintf(stderr,"Invalid report JSON\n");return 3;}CTFontManagerRegisterFontsForURL((__bridge CFURLRef)[NSURL fileURLWithPath:@(argv[2])],kCTFontManagerScopeProcess,NULL);CFArrayRef descriptors=CTFontManagerCreateFontDescriptorsFromURL((__bridge CFURLRef)[NSURL fileURLWithPath:@(argv[2])]);if(descriptors&&CFArrayGetCount(descriptors)){reportFontName=CFBridgingRelease(CTFontDescriptorCopyAttribute((CTFontDescriptorRef)CFArrayGetValueAtIndex(descriptors,0),kCTFontNameAttribute));}if(descriptors)CFRelease(descriptors);eventName=data[@"event"]?:@"Tournament";reportTitle=data[@"title"]?:@"Report";NSArray *rounds=data[@"bracket"];if(rounds.count){W=MAX(842,rounds.count*240+72);H=MAX(595,[rounds[0][@"series"] count]*112+150);}else if([data[@"landscape"] boolValue]){W=842;H=595;}CGRect box=CGRectMake(0,0,W,H);ctx=CGPDFContextCreateWithURL((__bridge CFURLRef)[NSURL fileURLWithPath:@(argv[1])],&box,(__bridge CFDictionaryRef)@{(id)kCGPDFContextTitle:reportTitle,(id)kCGPDFContextCreator:@"Tournament Manager"});if(!ctx){fprintf(stderr,"Cannot create PDF\n");return 4;}beginPage();if(rounds.count){NSUInteger base=[rounds[0][@"series"] count];CGFloat usable=H-150;for(NSUInteger c=0;c<rounds.count;c++){NSDictionary *round=rounds[c];NSArray *series=round[@"series"];text(round[@"name"],36+c*240,99,212,25,13,YES,NSColor.blackColor);for(NSUInteger i=0;i<series.count;i++){NSDictionary *s=series[i];CGFloat cy=130+(i+.5)*usable/MAX(1,series.count),x=36+c*240;if(c){NSUInteger prev=[rounds[c-1][@"series"] count];for(NSUInteger k=2*i;k<MIN(2*i+2,prev);k++){CGFloat py=130+(k+.5)*usable/prev;CGContextSetStrokeColorWithColor(ctx,NSColor.grayColor.CGColor);CGContextSetLineWidth(ctx,1);CGContextMoveToPoint(ctx,x-28,py);CGContextAddLineToPoint(ctx,x-14,py);CGContextAddLineToPoint(ctx,x-14,cy);CGContextAddLineToPoint(ctx,x,cy);CGContextStrokePath(ctx);}}rect(x,cy-38,212,76,[NSColor colorWithSRGBRed:.97 green:.94 blue:.99 alpha:1]);drawOutline(x,cy-38,212,76);NSArray *teams=s[@"teams"],*wins=s[@"wins"];for(int a=0;a<2;a++){BOOL won=[s[@"winner"] isKindOfClass:NSNumber.class]&&[s[@"winner"] intValue]==a;text(teams[a],x+7,cy-33+a*36,175,34,10,won,won?[NSColor colorWithSRGBRed:.12 green:.42 blue:.22 alpha:1]:NSColor.blackColor);text([wins[a] description],x+190,cy-30+a*36,18,30,11,YES,NSColor.blackColor);}}}(void)base;}else{for(NSDictionary *section in data[@"sections"]){NSString *name=section[@"name"];if(name.length){if(y>H-100)beginPage();text(name,36,y,W-72,34,13,YES,NSColor.blackColor);y+=36;}table(section[@"columns"],section[@"widths"],section[@"rows"],section[@"row_colors"]);y+=22;}}endPage();CGPDFContextClose(ctx);CGContextRelease(ctx);return 0;}}
